input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?p (count(*) as ?c) WHERE {
  ?s brick:hasProperty ?p .
  ?p a ?cls .
} GROUP BY ?cls ORDER BY DESC(?c) LIMIT 50

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?label WHERE {
  ?zone a brick:Zone ; rdfs:label ?label .
  FILTER (?label IN ("Core_bottom","Perimeter_bot_ZN_4","Perimeter_top_ZN_1"))
} LIMIT 10

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?s ?p ?o WHERE {
  ?s rdfs:label ?o .
} LIMIT 30

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
SELECT ?s ?o WHERE {
  ?s a brick:Zone .
  OPTIONAL { ?s rdfs:label ?o }
} LIMIT 50

SELECT ?p (count(*) as ?c) WHERE {
  ?s ?p ?o .
} GROUP BY ?p ORDER BY DESC(?c) LIMIT 30

SELECT ?o (count(*) as ?c) WHERE {
  ?s a ?o .
} GROUP BY ?o ORDER BY DESC(?c) LIMIT 30

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?label WHERE {
  ?z a brick:HVAC_Zone .
  OPTIONAL { ?z rdfs:label ?label }
} LIMIT 50

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?s WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label ?label .
  FILTER (?label IN ("Core_bottom","Perimeter_bot_ZN_4","Perimeter_top_ZN_1"))
  ?s brick:isPointOf ?z .
  ?s a brick:Electric_Power_Sensor .
  OPTIONAL { ?s rdfs:label ?slabel }
} LIMIT 40
